{
  "name": "wrist-rhythm",
  "version": "1.0.0",
  "description": "openvela 腕上身心训练快应用",
  "private": true,
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "start": "aiot server --watch --open-nuttx",
    "build": "aiot build",
    "build:release": "node scripts/release-runner.js",
    "release": "npm run build:release",
    "watch": "aiot watch --open-nuttx",
    "test:logic": "node test/steady.test.js && node test/runtime.test.js && node test/page-lifecycle.test.js && node test/component-contract.test.js && node test/release-runner.test.js",
    "test": "npm run test:logic"
  },
  "devDependencies": {
    "@aiot-toolkit/jsc": "^1.0.8",
    "@aiot-toolkit/velasim": "^0.1.26",
    "aiot-toolkit": "2.0.5",
    "ux-types": "^1.7.0"
  }
}

<template>
  <div class="page breathing-page breathing-page-{{ screenSize }} breathing-page-{{ screenViewport }}">
    <text class="session-label">稳态训练</text>
    <text class="remaining">{{ remainingText }}</text>

    <div class="orb-shell orb-shell-{{ screenSize }} orb-shell-{{ screenViewport }}">
      <div class="breath-halo breath-halo-{{ screenViewport }} {{ breathPhase }}">
        <div class="breath-orb breath-orb-{{ screenViewport }} {{ breathPhase }}">
          <div class="orb-core {{ breathPhase }}-core"></div>
        </div>
      </div>
    </div>

    <text class="phase-label phase-label-{{ screenViewport }}">{{ phaseLabel }}</text>
    <text class="pattern-label">{{ patternLabel }}</text>
    <div class="stop-button stop-button-{{ screenViewport }}" onclick="stopTraining">
      <text class="stop-text">结束训练</text>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    screenSize: { type: String, default: 'regular' },
    screenViewport: { type: String, default: 'normal' },
    remainingText: { type: String, default: '60' },
    breathPhase: { type: String, default: 'inhale' },
    phaseLabel: { type: String, default: '慢慢吸气' },
    patternLabel: { type: String, default: '标准节奏 · 4-2-4' },
  },
  stopTraining() { this.$emit('stopTraining'); },
};
</script>

<style>
.page {
  width: 100%;
  height: 100%;
  flex-direction: column;
  align-items: center;
}

.breathing-page {
  padding-top: 28px;
}

.session-label {
  font-size: 13px;
  letter-spacing: 2px;
  color: #76998d;
}

.remaining {
  margin-top: 1px;
  font-size: 30px;
  font-weight: 700;
  color: #f3f6f5;
}

.orb-shell {
  width: 250px;
  height: 250px;
  margin-top: 8px;
  border-width: 1px;
  border-color: #173d33;
  border-radius: 125px;
  justify-content: center;
  align-items: center;
  background-color: #091b17;
}

.breath-halo {
  border-width: 1px;
  border-color: #2b6c58;
  border-radius: 110px;
  justify-content: center;
  align-items: center;
  background-color: #0f2c24;
  transition-property: width, height, opacity, background-color;
  transition-duration: 3600ms;
  transition-timing-function: ease-in-out;
}

.breath-halo.inhale {
  width: 220px;
  height: 220px;
}

.breath-halo.hold {
  width: 208px;
  height: 208px;
  border-color: #66cdb1;
  transition-duration: 1200ms;
}

.breath-halo.exhale {
  width: 154px;
  height: 154px;
}

.breath-orb {
  border-radius: 100px;
  justify-content: center;
  align-items: center;
  background-color: #285f4d;
  transition-property: width, height, opacity, background-color;
  transition-duration: 3600ms;
  transition-timing-function: ease-in-out;
}

.breath-orb.inhale {
  width: 184px;
  height: 184px;
  background-color: #1c5e4a;
}

.breath-orb.hold {
  width: 174px;
  height: 174px;
  background-color: #28725b;
  transition-duration: 1200ms;
}

.breath-orb.exhale {
  width: 120px;
  height: 120px;
  background-color: #164636;
}

.orb-core {
  width: 38px;
  height: 38px;
  border-radius: 19px;
  background-color: #c8f5e8;
  transition-property: transform, opacity, background-color;
  transition-duration: 1200ms;
  transition-timing-function: ease-in-out;
}

.inhale-core {
  opacity: 1;
  transform: scale(1.12);
  animation-name: core-breathe;
  animation-duration: 3600ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
}

.hold-core {
  opacity: 0.88;
  transform: scale(1);
  animation-name: core-hover;
  animation-duration: 1200ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
  animation-direction: alternate;
}

.exhale-core {
  opacity: 0.68;
  transform: scale(0.78);
  animation-name: core-release;
  animation-duration: 3600ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
}

@keyframes core-breathe {
  0% { opacity: 0.62; transform: scale(0.78); }
  100% { opacity: 1; transform: scale(1.12); }
}

@keyframes core-hover {
  0% { opacity: 0.78; transform: scale(0.96); }
  100% { opacity: 0.94; transform: scale(1.04); }
}

@keyframes core-release {
  0% { opacity: 1; transform: scale(1.12); }
  100% { opacity: 0.68; transform: scale(0.78); }
}

.phase-label {
  margin-top: 10px;
  font-size: 27px;
  font-weight: 600;
  color: #ffffff;
}

.pattern-label {
  margin-top: 2px;
  font-size: 13px;
  color: #75968b;
}

.stop-button {
  width: 150px;
  height: 42px;
  margin-top: 12px;
  border-width: 1px;
  border-color: #315347;
  border-radius: 21px;
  justify-content: center;
  align-items: center;
}

.stop-text {
  font-size: 14px;
  color: #9aafa8;
}

/* 小尺寸设备优先保证操作区和底部按钮完整可见。 */
.breathing-page-compact {
  padding-top: 20px;
}

.orb-shell-compact {
  width: 230px;
  height: 230px;
  border-radius: 115px;
}

/* 短视口压缩纵向节奏，确保圆屏主操作始终可见。 */
.breathing-page-short {
  padding-top: 8px;
}

.orb-shell-short {
  width: 130px;
  height: 130px;
  margin-top: 2px;
  border-radius: 65px;
}

.breath-halo-short.inhale,
.breath-halo-short.hold {
  width: 116px;
  height: 116px;
}

.breath-halo-short.exhale {
  width: 86px;
  height: 86px;
}

.breath-orb-short.inhale,
.breath-orb-short.hold {
  width: 108px;
  height: 108px;
}

.breath-orb-short.exhale {
  width: 76px;
  height: 76px;
}

.phase-label-short {
  margin-top: 2px;
  font-size: 26px;
}

.stop-button-short {
  height: 32px;
  margin-top: 4px;
}
</style>

<import name="home-view" src="./components/home.ux"></import>
<import name="steady-result-view" src="./components/steady-result.ux"></import>
<import name="boxing-result-view" src="./components/boxing-result.ux"></import>
<import name="breathing-view" src="./components/breathing.ux"></import>
<import name="boxing-view" src="./components/boxing.ux"></import>

<template>
  <div class="app {{ screenClass }}">
    <home-view
      if="{{ view === 'home' }}"
      screen-size="{{ screenSize }}"
      screen-viewport="{{ screenViewport }}"
      suggest="{{ suggest }}"
      vital-pulse-class="{{ vitalPulseClass }}"
      status-title="{{ statusTitle }}"
      status-subtitle="{{ statusSubtitle }}"
      heart-rate-text="{{ heartRateText }}"
      stress-text="{{ stressText }}"
      health-message="{{ healthMessage }}"
      onstart-training="startTraining"
      onstart-boxing="startBoxing">
    </home-view>

    <breathing-view
      if="{{ view === 'breathing' }}"
      screen-size="{{ screenSize }}"
      screen-viewport="{{ screenViewport }}"
      remaining-text="{{ remainingText }}"
      breath-phase="{{ breathPhase }}"
      phase-label="{{ phaseLabel }}"
      pattern-label="{{ patternLabel }}"
      onstop-training="stopTraining">
    </breathing-view>

    <steady-result-view
      if="{{ view === 'result' }}"
      screen-size="{{ screenSize }}"
      screen-viewport="{{ screenViewport }}"
      result-heart-rate-detail="{{ resultHeartRateDetail }}"
      result-heart-rate-delta="{{ resultHeartRateDelta }}"
      result-stress-detail="{{ resultStressDetail }}"
      result-stress-delta="{{ resultStressDelta }}"
      heart-rate-improved="{{ heartRateImproved }}"
      stress-improved="{{ stressImproved }}"
      onreturn-home="returnHome">
    </steady-result-view>

    <boxing-view
      if="{{ view === 'boxing' }}"
      screen-size="{{ screenSize }}"
      screen-viewport="{{ screenViewport }}"
      boxing-remaining-text="{{ boxingRemainingText }}"
      boxing-score-text="{{ boxingScoreText }}"
      boxing-streak-text="{{ boxingStreakText }}"
      boxing-prompt="{{ boxingPrompt }}"
      boxing-pace-label="{{ boxingPaceLabel }}"
      boxing-target-class="{{ boxingTargetClass }}"
      boxing-fallback="{{ boxingFallback }}"
      boxing-message="{{ boxingMessage }}"
      onsimulate-punch="simulatePunch"
      onstop-boxing="stopBoxing">
    </boxing-view>

    <boxing-result-view
      if="{{ view === 'boxingResult' }}"
      screen-size="{{ screenSize }}"
      screen-viewport="{{ screenViewport }}"
      boxing-result-score="{{ boxingResultScore }}"
      boxing-result-hits="{{ boxingResultHits }}"
      boxing-result-streak="{{ boxingResultStreak }}"
      boxing-result-heart-rate="{{ boxingResultHeartRate }}"
      onreturn-home="returnHome">
    </boxing-result-view>
  </div>
</template>

<script>
import steady from './steady.js';
import boxing from './boxing.js';
import reactive from './reactive.js';
import clock from './session-clock.js';
import lifecycle from './page-lifecycle.js';
import { getRecent, subscribe, unsubscribe, DATA_TYPES } from './health.js';
import { subscribeAccelerometer, unsubscribeAccelerometer } from './motion.js';
import { getScreenLayout } from './device.js';

const TYPES = [DATA_TYPES.HEART_RATE, DATA_TYPES.STRESS];

function displayValue(value) {
  return typeof value === 'number' ? String(Math.round(value)) : '--';
}

function displayDelta(value, unit) {
  if (typeof value !== 'number') return '暂无数据';
  const prefix = value > 0 ? '+' : '';
  return `${prefix}${value} ${unit}`;
}

function displayPair(before, after, unit) {
  if (typeof before !== 'number' || typeof after !== 'number') return '训练期间未取得数据';
  return `${before} → ${after} ${unit}`;
}

export default {
  private: {
    screenClass: 'screen-round size-regular',
    screenSize: 'regular',
    screenViewport: 'normal',
    view: 'home',
    heartRate: null,
    stress: null,
    heartRates: [],
    stresses: [],
    heartRateText: '--',
    stressText: '--',
    suggest: false,
    vitalPulseClass: 'pulse-a',
    vitalPulseGeneration: 0,
    statusTitle: '正在感受你的节律',
    statusSubtitle: '保持自然，数据将很快出现',
    healthMessage: '',
    trainingClock: null,
    boxingClock: null,
    resourceController: null,
    visible: false,
    cycleStartElapsed: 0,
    currentPattern: steady.PATTERNS.standard,
    patternLabel: '标准节奏 · 4-2-4',
    breathPhase: 'inhale',
    phaseLabel: '慢慢吸气',
    remainingText: '60',
    timer: null,
    baseline: { heartRate: null, stress: null },
    resultHeartRateDetail: '',
    resultHeartRateDelta: '',
    resultStressDetail: '',
    resultStressDelta: '',
    heartRateImproved: false,
    stressImproved: false,
    boxingBeatAt: 0,
    boxingNextBeatAt: 0,
    boxingBeatHit: false,
    boxingStats: boxing.createStats(),
    boxingDetector: null,
    boxingRemainingText: '30',
    boxingScoreText: '0',
    boxingStreakText: '0',
    boxingPrompt: '准备',
    boxingPaceLabel: '正在读取心率节拍',
    boxingTargetClass: 'target-waiting',
    boxingFallback: false,
    boxingMessage: '',
    motionConnected: false,
    motionConnectTimer: null,
    boxingBaselineHeartRate: null,
    boxingResultScore: '0',
    boxingResultHits: '0 / 0',
    boxingResultStreak: '0',
    boxingResultHeartRate: '训练期间未取得数据',
  },

  onReady() {
    getScreenLayout().then((screenLayout) => this.applyScreenLayout(screenLayout));
  },

  onShow() {
    this.visible = true;
    this.ensureResourceController().enterForeground();
    this.startHealth();
    this.resumeActiveSession(Date.now());
  },

  onHide() {
    this.visible = false;
    this.ensureResourceController().leaveForeground();
    this.pauseActiveSession(Date.now());
    this.stopRuntimeResources();
    this.stopHealth();
  },

  onDestroy() {
    this.visible = false;
    this.ensureResourceController().leaveForeground();
    this.stopRuntimeResources();
    this.stopHealth();
  },

  applyScreenLayout(screenLayout) {
    this.screenClass = screenLayout.className;
    this.screenSize = screenLayout.size;
    this.screenViewport = screenLayout.viewport;
  },

  ensureResourceController() {
    if (this.resourceController === null) {
      this.resourceController = lifecycle.createResourceController({
        healthTypes: TYPES,
        getRecentHealth: getRecent,
        subscribeHealth: subscribe,
        unsubscribeHealth: unsubscribe,
        subscribeMotion: subscribeAccelerometer,
        unsubscribeMotion: unsubscribeAccelerometer,
        onHealthSample: (sample) => this.applySample(sample),
        onHealthError: (error) => this.applyHealthError(error),
        onMotionSample: (sample) => this.applyMotionSample(sample),
        onMotionError: (error) => this.enableBoxingFallback(error),
      });
    }
    return this.resourceController;
  },

  startHealth() {
    const needsRecent = this.heartRate === null && this.stress === null;
    this.ensureResourceController().startHealth(needsRecent);
  },

  stopHealth() {
    this.ensureResourceController().stopHealth();
  },

  applySample(sample) {
    if (!sample || !sample.ok) return;
    if (sample.dataType === DATA_TYPES.HEART_RATE) {
      this.heartRate = sample.value;
      this.heartRateText = displayValue(sample.value);
      this.heartRates = steady.pushWindow(
        this.heartRates,
        sample.value,
        steady.SAMPLE_WINDOW,
      );
    } else if (sample.dataType === DATA_TYPES.STRESS) {
      this.stress = sample.value;
      this.stressText = displayValue(sample.value);
      this.stresses = steady.pushWindow(this.stresses, sample.value, steady.SAMPLE_WINDOW);
    }
    if (this.view === 'home') {
      this.vitalPulseGeneration += 1;
      this.vitalPulseClass = this.vitalPulseGeneration % 2 === 0 ? 'pulse-a' : 'pulse-b';
    }
    this.healthMessage = '';
    this.updateSuggestion();
  },

  applyHealthError(error) {
    this.healthMessage = error && error.unsupported
      ? '当前设备暂不支持健康数据'
      : '健康数据暂不可用，仍可进行训练';
  },

  updateSuggestion() {
    const state = steady.shouldSuggest(this.heartRates, this.stresses);
    this.suggest = state.suggest;
    if (state.suggest) {
      this.statusTitle = '建议缓一缓';
      this.statusSubtitle = '用一分钟找回平稳节律';
    } else if (this.heartRate !== null || this.stress !== null) {
      this.statusTitle = '当前节律平稳';
      this.statusSubtitle = '也可以主动做一次呼吸训练';
    }
  },

  startTraining() {
    this.clearTimer();
    this.baseline = { heartRate: this.heartRate, stress: this.stress };
    this.currentPattern = steady.selectPattern(this.stress, this.heartRate, this.heartRate);
    this.cycleStartElapsed = 0;
    this.trainingClock = clock.createClock(steady.SESSION_MS, Date.now());
    this.view = 'breathing';
    this.updatePatternLabel();
    this.tick();
    this.timer = setInterval(() => this.tick(), 250);
  },

  tick() {
    const now = Date.now();
    const elapsed = clock.elapsedMs(this.trainingClock, now);
    if (clock.isComplete(this.trainingClock, now)) {
      this.completeTraining();
      return;
    }

    let cycleElapsed = elapsed - this.cycleStartElapsed;
    let cycleDuration = this.patternDuration(this.currentPattern);
    if (cycleElapsed >= cycleDuration) {
      this.cycleStartElapsed += cycleDuration;
      this.currentPattern = steady.selectPattern(
        this.stress,
        this.heartRate,
        this.baseline.heartRate,
      );
      cycleElapsed = elapsed - this.cycleStartElapsed;
      cycleDuration = this.patternDuration(this.currentPattern);
      if (cycleElapsed >= cycleDuration) this.cycleStartElapsed = elapsed;
      this.updatePatternLabel();
    }

    const phase = steady.phaseAt(elapsed - this.cycleStartElapsed, this.currentPattern);
    reactive.writeIfChanged(this, 'breathPhase', phase.phase);
    reactive.writeIfChanged(this, 'phaseLabel', phase.label);
    reactive.writeIfChanged(this, 'remainingText', String(Math.ceil((steady.SESSION_MS - elapsed) / 1000)));
  },

  patternDuration(pattern) {
    return pattern.inhaleMs + pattern.holdMs + pattern.exhaleMs;
  },

  updatePatternLabel() {
    this.patternLabel = this.currentPattern.name === 'calming'
      ? '舒缓节奏 · 4-2-6'
      : '标准节奏 · 4-2-4';
  },

  stopTraining() {
    this.clearTimer();
    this.view = 'home';
  },

  completeTraining() {
    this.clearTimer();
    const result = steady.buildResult(this.baseline, {
      heartRate: this.heartRate,
      stress: this.stress,
    });
    this.resultHeartRateDetail = displayPair(
      result.beforeHeartRate,
      result.afterHeartRate,
      'bpm',
    );
    this.resultHeartRateDelta = displayDelta(result.heartRateDelta, 'bpm');
    this.resultStressDetail = displayPair(result.beforeStress, result.afterStress, '分');
    this.resultStressDelta = displayDelta(result.stressDelta, '分');
    this.heartRateImproved = typeof result.heartRateDelta === 'number' && result.heartRateDelta < 0;
    this.stressImproved = typeof result.stressDelta === 'number' && result.stressDelta < 0;
    this.view = 'result';
  },

  clearTimer() {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  },

  returnHome() {
    this.view = 'home';
  },

  pauseActiveSession(now) {
    if (this.view === 'breathing') {
      this.trainingClock = clock.pauseClock(this.trainingClock, now);
    } else if (this.view === 'boxing') {
      this.boxingClock = clock.pauseClock(this.boxingClock, now);
    }
  },

  resumeActiveSession(now) {
    if (this.view === 'breathing') {
      lifecycle.resumeSession(this.trainingClock, now, {
        updateClock: (resumedClock) => { this.trainingClock = resumedClock; },
        complete: () => this.completeTraining(),
        rearm: () => {
          this.tick();
          if (this.view === 'breathing' && this.timer === null) {
            this.timer = setInterval(() => this.tick(), 250);
          }
        },
      });
    } else if (this.view === 'boxing') {
      const wasPaused = this.boxingClock && this.boxingClock.pausedAt !== null;
      lifecycle.resumeSession(this.boxingClock, now, {
        updateClock: (resumedClock) => { this.boxingClock = resumedClock; },
        complete: () => this.finishBoxing(),
        rearm: () => {
          if (wasPaused) {
            const elapsed = clock.elapsedMs(this.boxingClock, now);
            const interval = boxing.beatIntervalForHeartRate(this.heartRate);
            this.boxingBeatAt = 0;
            this.boxingBeatHit = false;
            this.boxingNextBeatAt = clock.nextBeatAfterResume(elapsed, interval);
            this.motionConnected = false;
            this.boxingFallback = false;
            this.boxingMessage = '正在连接动作传感器';
          }
          this.startBoxingRuntime();
          this.boxingTick();
        },
      });
    }
  },

  startBoxing() {
    this.stopRuntimeResources();
    this.boxingClock = clock.createClock(boxing.GAME_MS, Date.now());
    this.boxingBeatAt = 0;
    this.boxingNextBeatAt = 900;
    this.boxingBeatHit = false;
    this.boxingStats = boxing.createStats();
    this.boxingDetector = boxing.createPunchDetector();
    this.boxingRemainingText = '30';
    this.boxingScoreText = '0';
    this.boxingStreakText = '0';
    this.boxingPrompt = '准备';
    this.boxingPaceLabel = '正在读取心率节拍';
    this.boxingTargetClass = 'target-waiting';
    this.boxingFallback = false;
    this.boxingMessage = '正在连接动作传感器';
    this.motionConnected = false;
    this.boxingBaselineHeartRate = this.heartRate;
    this.view = 'boxing';
    this.startBoxingRuntime();
  },

  startBoxingRuntime() {
    this.ensureResourceController().startMotion();
    if (this.motionConnectTimer === null) {
      this.motionConnectTimer = setTimeout(() => {
        if (!this.motionConnected && this.view === 'boxing') this.enableBoxingFallback();
      }, 1600);
    }
    if (this.timer === null) this.timer = setInterval(() => this.boxingTick(), 50);
  },

  applyMotionSample(sample) {
    if (this.view !== 'boxing') return;
    if (!this.motionConnected) {
      this.motionConnected = true;
      this.boxingMessage = '';
      this.clearMotionConnectTimer();
    }
    const now = Date.now();
    if (this.boxingDetector && this.boxingDetector.push(sample, now)) this.registerPunch(now);
  },

  enableBoxingFallback() {
    if (this.view !== 'boxing') return;
    this.clearMotionConnectTimer();
    this.stopMotion();
    this.boxingFallback = true;
    this.boxingMessage = '未检测到动作数据，已开启模拟模式';
  },

  boxingTick() {
    const now = Date.now();
    const elapsed = clock.elapsedMs(this.boxingClock, now);
    if (clock.isComplete(this.boxingClock, now)) {
      this.finishBoxing();
      return;
    }
    reactive.writeIfChanged(this, 'boxingRemainingText', String(Math.ceil((boxing.GAME_MS - elapsed) / 1000)));

    if (this.boxingBeatAt && !this.boxingBeatHit && elapsed - this.boxingBeatAt > boxing.HIT_WINDOW_MS) {
      this.boxingStats = boxing.recordMiss(this.boxingStats);
      this.boxingBeatAt = 0;
      this.boxingPrompt = '跟上节拍';
      this.boxingTargetClass = 'target-missed';
      this.syncBoxingStats();
    }

    if (elapsed >= this.boxingNextBeatAt) {
      const interval = boxing.beatIntervalForHeartRate(this.heartRate);
      this.boxingBeatAt = this.boxingNextBeatAt;
      this.boxingNextBeatAt += interval;
      this.boxingBeatHit = false;
      this.boxingPrompt = '出拳！';
      this.boxingTargetClass = 'target-active';
      this.boxingPaceLabel = interval === 1000
        ? '活力节拍 · 60 次/分'
        : interval === 1200
          ? '平衡节拍 · 50 次/分'
          : '舒缓节拍 · 43 次/分';
    }
  },

  registerPunch(timestamp) {
    if (!this.boxingBeatAt || this.boxingBeatHit) {
      this.boxingPrompt = '等节拍亮起';
      return;
    }
    const effectiveElapsed = clock.elapsedMs(this.boxingClock, timestamp);
    const scored = boxing.scorePunch(effectiveElapsed, this.boxingBeatAt);
    if (!scored.points) return;
    this.boxingStats = boxing.recordHit(this.boxingStats, scored.points);
    this.boxingBeatHit = true;
    this.boxingBeatAt = 0;
    this.boxingTargetClass = 'target-hit';
    this.boxingPrompt = scored.grade === 'perfect'
      ? '精准！'
      : scored.grade === 'good'
        ? '很好！'
        : '命中';
    this.syncBoxingStats();
  },

  simulatePunch() {
    if (this.boxingFallback && this.view === 'boxing') this.registerPunch(Date.now());
  },

  syncBoxingStats() {
    this.boxingScoreText = String(this.boxingStats.score);
    this.boxingStreakText = String(this.boxingStats.streak);
  },

  stopBoxing() {
    this.stopRuntimeResources();
    this.view = 'home';
  },

  finishBoxing() {
    if (this.boxingBeatAt && !this.boxingBeatHit) {
      this.boxingStats = boxing.recordMiss(this.boxingStats);
    }
    this.stopRuntimeResources();
    this.boxingResultScore = String(this.boxingStats.score);
    this.boxingResultHits = `${this.boxingStats.hits} / ${this.boxingStats.targets}`;
    this.boxingResultStreak = String(this.boxingStats.maxStreak);
    this.boxingResultHeartRate = displayPair(
      this.boxingBaselineHeartRate,
      this.heartRate,
      'bpm',
    );
    this.view = 'boxingResult';
  },

  clearMotionConnectTimer() {
    if (this.motionConnectTimer !== null) {
      clearTimeout(this.motionConnectTimer);
      this.motionConnectTimer = null;
    }
  },

  stopMotion() {
    this.ensureResourceController().stopMotion();
  },

  stopRuntimeResources() {
    this.clearTimer();
    this.clearMotionConnectTimer();
    this.stopMotion();
  },
};
